//! Signed, monotonic per-account revocation snapshots; no network on session checks.
use crate::collab::{auth, authority, db};
use rusqlite::{params, OptionalExtension};
use serde::{Deserialize, Serialize};

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Revocation {
    pub device_id: String,
    pub node_id: String,
    pub revoked_at: i64,
    pub version: i64,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Snapshot {
    pub uid: String,
    pub version: i64,
    pub issued_at: i64,
    pub revoked: Vec<Revocation>,
    pub devices: Vec<super::devices::Device>,
    pub first_device: Option<String>,
}

pub fn signed(uid: &str) -> Result<String, String> {
    let conn = db::open_db()?;
    let tx = conn.unchecked_transaction().map_err(|e| e.to_string())?;
    let version = tx.query_row("SELECT version FROM mesh_revocation_versions WHERE uid=?1",
        params![uid], |r| r.get(0)).optional().map_err(|e| e.to_string())?.map_or(0, |v| v);
    let mut st = tx.prepare(
        "SELECT device_id,node_id,revoked_at,version FROM mesh_revocations WHERE uid=?1 ORDER BY version",
    ).map_err(|e| e.to_string())?;
    let revoked = st.query_map(params![uid], |r| Ok(Revocation {
        device_id: r.get(0)?, node_id: r.get(1)?, revoked_at: r.get(2)?, version: r.get(3)?,
    })).map_err(|e| e.to_string())?.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())?;
    let mut st = tx.prepare("SELECT d.device_id,d.node_id,d.enrolled_at,d.sequence
        FROM mesh_device_ids d JOIN mesh_nodes m ON m.node_id=d.node_id AND m.uid=d.uid
        WHERE d.uid=?1 AND m.revoked=0").map_err(|e| e.to_string())?;
    let devices = st.query_map(params![uid], |r| Ok(super::devices::Device {
        device_id:r.get(0)?, node_id:r.get(1)?, enrolled_at:r.get(2)?, sequence:r.get(3)?,
    })).map_err(|e| e.to_string())?.collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string())?;
    let first_device = tx.query_row("SELECT device_id FROM mesh_first_device WHERE uid=?1",
        params![uid], |r| r.get(0)).optional().map_err(|e| e.to_string())?;
    authority::sign_document("PR1", &Snapshot {
        uid: uid.into(), version, issued_at: db::now(), revoked, devices, first_device,
    })
}

pub fn accept(uid: &str, document: &str) -> Result<(), String> {
    let (_, key, _) = authority::pinned().ok_or("吊销清单缺少已钉住的权威公钥")?;
    let config = super::load()?;
    if !config.authority.public_key_fingerprints.is_empty() { config.verify_key(&key)?; }
    accept_with(uid, document, &key)
}

pub(crate) fn accept_with(uid: &str, document: &str, key: &str) -> Result<(), String> {
    let snapshot: Snapshot = authority::verify_document("PR1", document, key)?;
    if snapshot.uid != uid || uid.is_empty() || snapshot.version < 0
        || snapshot.issued_at > db::now() + 30 || snapshot.issued_at <= 0
        || snapshot.revoked.iter().any(|r| r.device_id.is_empty() || r.node_id.is_empty()
            || r.version <= 0 || r.version > snapshot.version || r.revoked_at > snapshot.issued_at)
    { return Err("吊销清单账号、版本或时间无效".into()); }
    let mut conn = db::open_db()?;
    let tx = conn.transaction_with_behavior(rusqlite::TransactionBehavior::Immediate)
        .map_err(|e| e.to_string())?;
    let previous: Option<(i64, i64)> = tx.query_row(
        "SELECT version,issued_at FROM cached_revocation_lists WHERE uid=?1", params![uid],
        |r| Ok((r.get(0)?, r.get(1)?)),
    ).optional().map_err(|e| e.to_string())?;
    if previous.is_some_and(|(version, issued)| snapshot.version < version || snapshot.issued_at < issued) {
        return Err("吊销清单回退，保留最后有效清单".into());
    }
    for r in &snapshot.revoked {
        let inserted = tx.execute(
            "INSERT OR IGNORE INTO cached_revocations(uid,device_id,node_id,revoked_at) VALUES(?1,?2,?3,?4)",
            params![uid, r.device_id, r.node_id, r.revoked_at],
        ).map_err(|e| e.to_string())?;
        // Only retract existing same-account contracts; authority never creates permissions.
        if inserted > 0 {
            tx.execute("UPDATE peer_grants SET revoked=1 WHERE uid=?1 AND node_id=?2",
                params![uid, r.node_id]).map_err(|e| e.to_string())?;
        }
    }
    tx.execute(
        "DELETE FROM sessions WHERE token IN (SELECT b.token FROM bound_sessions b
         JOIN cached_revocations r ON r.uid=b.uid AND r.device_id=b.device_id)", [],
    ).map_err(|e| e.to_string())?;
    tx.execute(
        "INSERT INTO cached_revocation_lists(uid,version,issued_at,document) VALUES(?1,?2,?3,?4)
         ON CONFLICT(uid) DO UPDATE SET version=excluded.version,issued_at=excluded.issued_at,document=excluded.document",
        params![uid, snapshot.version, snapshot.issued_at, document],
    ).map_err(|e| e.to_string())?;
    tx.commit().map_err(|e| e.to_string())?;
    auth::bump_session_revocation();
    Ok(())
}

pub fn is_revoked(uid: &str, device: &str) -> Result<bool, String> {
    db::with_conn(|conn| conn.query_row(
        "SELECT EXISTS(SELECT 1 FROM cached_revocations WHERE uid=?1 AND device_id=?2)
         OR EXISTS(SELECT 1 FROM mesh_revocations WHERE uid=?1 AND device_id=?2)",
        params![uid, device], |r| r.get(0),
    ).map_err(|e| e.to_string()))
}

pub fn require_fresh(uid: &str) -> Result<(), String> {
    let limit = super::load()?.security.revocation_max_age_secs as i64;
    let issued: Option<i64> = db::with_conn(|conn| conn.query_row(
        "SELECT issued_at FROM cached_revocation_lists WHERE uid=?1", params![uid], |r| r.get(0),
    ).optional().map_err(|e| e.to_string()))?;
    if !issued.is_some_and(|t| db::now() - t <= limit) {
        return Err("需要联网确认：吊销清单已过期或尚未同步".into());
    }
    Ok(())
}

/// Poll every federated member account, including guests not owned by the host's mesh account.
pub fn accounts() -> Result<Vec<String>, String> {
    db::with_conn(|conn| {
        let mut st = conn.prepare("SELECT DISTINCT uid FROM users WHERE uid<>''")
            .map_err(|e| e.to_string())?;
        let out = st.query_map([], |r| r.get(0)).map_err(|e| e.to_string())?
            .collect::<Result<Vec<_>, _>>().map_err(|e| e.to_string());
        out
    })
}

/// Verify cached authority policy data before using it for offline high-risk exemptions.
pub fn cached(uid: &str) -> Result<Snapshot, String> {
    require_fresh(uid)?;
    let (_, key, _) = authority::pinned().ok_or("需要联网确认：尚未信任权威")?;
    let config = super::load()?;
    if !config.authority.public_key_fingerprints.is_empty() { config.verify_key(&key)?; }
    let document: String = db::with_conn(|conn| conn.query_row(
        "SELECT document FROM cached_revocation_lists WHERE uid=?1", params![uid], |r| r.get(0),
    ).map_err(|e| e.to_string()))?;
    let snapshot: Snapshot = authority::verify_document("PR1", &document, &key)?;
    if snapshot.uid != uid { return Err("吊销清单账号不匹配".into()); }
    Ok(snapshot)
}
//! Security polling shares mesh lifecycle entry points but cannot be delayed by peer mounts.
use crate::collab::{authority, db};
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::Duration;

static RUNNING: AtomicBool = AtomicBool::new(false);

pub fn poll_account(url: &str, uid: &str, timeout: Duration) -> Result<(), String> {
    let value: serde_json::Value = ureq::AgentBuilder::new().timeout(timeout).build()
        .get(&format!("{url}/api/mesh/revocations")).query("uid", uid)
        .call().map_err(|e| e.to_string())?.into_json().map_err(|e| e.to_string())?;
    let document = value["document"].as_str().ok_or("权威未提供签名吊销清单")?;
    super::revocations::accept(uid, document)
}

pub fn start() {
    let Ok(handle) = tokio::runtime::Handle::try_current() else { return; };
    if RUNNING.swap(true, Ordering::SeqCst) { return; }
    handle.spawn(async {
        loop {
            let config = match super::load() {
                Ok(config) => config,
                Err(error) => {
                    eprintln!("[mesh-security] 配置无效: {error}");
                    tokio::time::sleep(Duration::from_secs(30)).await;
                    continue;
                }
            };
            let next = tokio::time::Instant::now() + Duration::from_secs(config.security.revocation_poll_secs);
            if let Some((url, _, _)) = authority::pinned() {
                match super::revocations::accounts() {
                    Ok(accounts) => {
                        let mut jobs = tokio::task::JoinSet::new();
                        for uid in accounts {
                            let url = url.clone();
                            let timeout = Duration::from_secs(config.security.revocation_poll_secs.min(10));
                            jobs.spawn_blocking(move || {
                                if let Err(error) = poll_account(&url, &uid, timeout) {
                                    eprintln!("[mesh-security] {uid}: 保留最后有效吊销清单: {error}");
                                    db::audit("system", "mesh.revocations.warning", &uid, &error);
                                }
                            });
                        }
                        while let Some(result) = jobs.join_next().await {
                            if let Err(error) = result { eprintln!("[mesh-security] 拉取任务失败: {error}"); }
                        }
                    }
                    Err(error) => eprintln!("[mesh-security] 账号查询失败: {error}"),
                }
            }
            tokio::time::sleep_until(next).await;
        }
    });
}
//! Shared high-risk adapter for HTTP actors and the local mesh console.
use crate::collab::{authority, db};
use rusqlite::{params, OptionalExtension};
use serde_json::{json, Value};

pub fn require(uid: &str, actor_node: &str, operation: &str, payload: &Value) -> Result<(), String> {
    require_proven(uid, actor_node, operation, payload, None)
}

pub fn require_proven(
    uid: &str, actor_node: &str, operation: &str, payload: &Value, assertion: Option<&str>,
) -> Result<(), String> {
    if uid.is_empty() { return Ok(()); }
    let digest = super::risk::digest(operation, payload);
    let nonce = crate::collab::auth::random_token();
    if authority::is_authority() {
        super::risk::authorize(uid, actor_node, actor_node, operation, &digest, &nonce)?;
        return Ok(());
    }
    let snapshot = super::revocations::cached(uid)?;
    let actor = snapshot.devices.iter().find(|device| device.node_id == actor_node)
        .ok_or("需要联网确认：最新清单尚未包含当前设备")?;
    if super::revocations::is_revoked(uid, &actor.device_id)? { return Err("设备已吊销".into()); }
    let window = super::load()?.security.new_device_window_hours as i64 * 3600;
    if snapshot.devices.len() == 1 || snapshot.first_device.as_deref() == Some(&actor.device_id)
        || db::now() >= actor.enrolled_at + window
    { return Ok(()); }
    let (url, key, _) = authority::pinned().ok_or("需要联网确认：尚未信任权威")?;
    let mesh_key = db::meta_get("mesh_key").ok_or("需要联网确认：本机尚未入网")?;
    let response = ureq::AgentBuilder::new().timeout(std::time::Duration::from_secs(10)).build()
        .post(&format!("{url}/api/mesh/risk/authorize"))
        .set("Authorization", &format!("Bearer {mesh_key}"))
        .send_json(json!({"actorNodeId":actor_node, "operation":operation, "digest":digest, "nonce":nonce, "actorAssertion":assertion}));
    let response: Value = match response {
        Ok(response) => response.into_json().map_err(|e| e.to_string())?,
        Err(ureq::Error::Status(_, response)) => {
            let value: Value = response.into_json().map_err(|e| e.to_string())?;
            return Err(value["error"].as_str().map_or_else(|| "需要联网确认".into(), String::from));
        }
        Err(error) => return Err(format!("需要联网确认：{error}")),
    };
    let document = response["permit"].as_str().ok_or("需要联网确认：权威未返回签名批准")?;
    let config = super::load()?;
    if !config.authority.public_key_fingerprints.is_empty() { config.verify_key(&key)?; }
    let permit: super::risk::Permit = authority::verify_document("PRISK1", document, &key)?;
    let host = db::meta_get("mesh_node_id").map_or_else(String::new, |v| v);
    if permit.uid != uid || permit.digest != digest || permit.nonce != nonce
        || permit.expires_at <= db::now() || permit.host != host
        || actor.device_id != permit.actor
    { return Err("高风险批准与当前设备、主机或操作不匹配".into()); }
    Ok(())
}

/// Legacy assertions retain their prior policy; bound sessions must use the approval gate.
pub fn session(token: &str, operation: &str, payload: &Value) -> Result<(), String> {
    session_proven(token, operation, payload, None)
}

pub fn session_proven(token: &str, operation: &str, payload: &Value, assertion: Option<&str>) -> Result<(), String> {
    crate::collab::auth::check_session(token)?;
    let binding: Option<(String, String)> = db::with_conn(|conn| conn.query_row(
        "SELECT uid,node_id FROM bound_sessions WHERE token=?1", params![token],
        |r| Ok((r.get(0)?, r.get(1)?)),
    ).optional().map_err(|e| e.to_string()))?;
    if let Some((uid, node)) = binding { require_proven(&uid, &node, operation, payload, assertion)?; }
    Ok(())
}
//! Contract view and effective permissions (policy B has no automatic cooldown).
use super::*;

#[derive(Serialize, Clone, Debug, PartialEq)]
pub struct Grant {
    pub node_id: String,
    pub uid: String,
    pub name: String,
    pub role: String,
    /// 库里存的档位(用户批的那个)。实际生效的档见 [`Grant::effective_fs`]。
    pub fs_access: String,
    pub exec_access: String,
    pub auto_mount: bool,
    pub drive_hint: String,
    pub cooldown_until: i64,
    pub granted_at: i64,
    pub granted_by: String,
    pub revoked: bool,
}

impl Grant {
    /// Compatibility field: policy B no longer restricts ordinary access by cooldown.
    pub fn in_cooldown(&self) -> bool {
        false
    }

    /// Effective disk permission respects explicit restrictions and revocation.
    pub fn effective_fs(&self) -> &str {
        if self.revoked {
            return FS_NONE;
        }
        &self.fs_access
    }

    /// Effective execution permission respects explicit restrictions and revocation.
    pub fn effective_exec(&self) -> &str {
        if self.revoked {
            return EXEC_NONE;
        }
        &self.exec_access
    }

    /// 这台设备现在该不该被自动连上并挂盘。
    pub fn should_mount(&self) -> bool {
        !self.revoked && self.auto_mount && self.effective_fs() != FS_NONE
    }
}

